// Valider les parametres
const input = $input.first().json;
const query = input.query || {};

const projectId = query.project_id || null;
const discordUserId = query.discord_user_id || null;

const errors = [];
if (!projectId) errors.push('project_id');
if (!discordUserId) errors.push('discord_user_id');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    project_id: projectId,
    discord_user_id: discordUserId
  }
}];

// Traiter la reponse de l'API /webhook/account
const apiResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

// Verifier si l'API a retourne une erreur ou pas de donnees
const statusCode = apiResponse.statusCode || 200;
const body = apiResponse.body || apiResponse;

// Detecter 404 de plusieurs facons (n8n peut wrapper differemment)
const errorStr = JSON.stringify(apiResponse);
const is404 = statusCode === 404 ||
              errorStr.includes('404') ||
              errorStr.includes('NOT_FOUND');

// CAS SPECIAL: 404 = nouvel utilisateur sans abonnement
// Retourner un profil 'free' par defaut au lieu d'une erreur
if (is404) {
  return [{
    json: {
      found: true,
      subscriber: {
        discord_user_id: inputData.discord_user_id,
        discord_username: null,
        email: null,
        plan_id: 'free',
        stripe_customer_id: null,
        credits_remaining: 0,
        credits_total: 0,
        credits_used: 0,
        usage_percent: 0,
        subscription_status: 'none',
        subscription_plan: 'free',
        current_period_end: null,
        is_active: false
      }
    }
  }];
}

// Autres erreurs API (500, etc.)
if (statusCode >= 400 || !body || body.error) {
  return [{
    json: {
      found: false,
      error: {
        code: statusCode >= 400 ? statusCode : 500,
        message: body?.error?.message || 'Erreur lors de la recuperation de l\'abonnement',
        status: 'API_ERROR'
      }
    }
  }];
}

// Mapper la reponse API /webhook/account vers le format attendu par le plugin
// Nouveau format: credits_remaining, credits_total, plan_id, subscription_status, current_period_end
const creditsRemaining = body.credits_remaining || 0;
const creditsTotal = body.credits_total || creditsRemaining;
const creditsUsed = creditsTotal - creditsRemaining;
const usagePercent = creditsTotal > 0
  ? Math.round((creditsUsed / creditsTotal) * 100)
  : 0;

const planId = body.plan_id || 'free';
const subscriptionStatus = body.subscription_status || 'free';
const isActive = subscriptionStatus === 'active';

return [{
  json: {
    found: true,
    subscriber: {
      discord_user_id: body.discord_user_id || inputData.discord_user_id,
      discord_username: body.discord_username || null,
      email: body.email || null,
      plan_id: planId,
      stripe_customer_id: body.stripe_customer_id || null,
      credits_remaining: creditsRemaining,
      credits_total: creditsTotal,
      credits_used: creditsUsed,
      usage_percent: usagePercent,
      subscription_status: subscriptionStatus,
      subscription_plan: planId,
      current_period_end: body.current_period_end || null,
      is_active: isActive
    }
  }
}];

